export const source="project KingCajun\n  @description \"Pedidos de mesa y domicilios con cupos, permisos y cancelaciones verificables.\"\n\nactor Waiter\n  @type person\n  @affiliation internal\n  @access authenticated\n  @signup invite\n\nactor Cook\n  @type person\n  @affiliation internal\n  @access authenticated\n  @signup invite\n\nactor Manager\n  @type person\n  @affiliation internal\n  @access authenticated\n  @signup invite\n\nactor DeliveryBot\n  @type system\n  @boundary external\n  @affiliation internal\n  @access none\n\nobject Slot\n  name: string\n  capacity: int\n  tickets: Ticket[]\n  booked: int = count of Ticket in tickets where status is not \"cancelled\"\n  @rule Slot.capacity is more than 0\n  @rule Slot.booked is at most Slot.capacity\n\nobject Ticket\n  reference: string\n  channel: table | delivery\n  status: reserved | new | cooking | ready | dispatched | served @final | cancel_requested | cancelled @final\n  slot: Slot\n  started: bool @default(false)\n  approved: bool @default(false)\n  confirmed: bool @default(false)\n  paymentRequired: bool @default(false)\n  paymentVerified: bool @default(false)\n\nstory Ordering\n  Waiter creates Ticket\n    requires Ticket.channel is \"table\"\n    sets Ticket.status to \"new\"\n  DeliveryBot reserves Ticket for Slot\n    # Onto evaluates this creation gate with the candidate already counted.\n    # Capacity 1 therefore permits the first ticket and refuses the second.\n    requires Slot.booked is at most Slot.capacity\n    requires Ticket.channel is \"delivery\"\n    sets Ticket.slot to Slot\n    sets Ticket.status to \"reserved\"\n  DeliveryBot accepts Ticket\n    requires Ticket.status is \"reserved\"\n    requires Ticket.confirmed is true\n    requires Ticket.paymentRequired is false or Ticket.paymentVerified is true\n    sets Ticket.status to \"new\"\n  DeliveryBot releases Ticket\n    requires Ticket.status is \"reserved\"\n    sets Ticket.status to \"cancelled\"\n\nstory Kitchen\n  Cook starts Ticket\n    requires Ticket.status is \"new\"\n    sets Ticket.started to true\n    sets Ticket.status to \"cooking\"\n  Cook finishes Ticket\n    requires Ticket.status is \"cooking\"\n    sets Ticket.status to \"ready\"\n  Waiter serves Ticket\n    requires Ticket.channel is \"table\"\n    requires Ticket.status is \"ready\"\n    sets Ticket.status to \"served\"\n  Waiter dispatches Ticket\n    requires Ticket.channel is \"delivery\"\n    requires Ticket.status is \"ready\"\n    sets Ticket.status to \"dispatched\"\n  Waiter delivers Ticket\n    requires Ticket.status is \"dispatched\"\n    sets Ticket.status to \"served\"\n\nstory Cancellations\n  Waiter requests Ticket\n    requires Ticket.status is \"new\" or Ticket.status is \"cooking\" or Ticket.status is \"ready\"\n    sets Ticket.status to \"cancel_requested\"\n  DeliveryBot requests Ticket\n    requires Ticket.status is \"new\" or Ticket.status is \"cooking\" or Ticket.status is \"ready\"\n    sets Ticket.status to \"cancel_requested\"\n  Manager approves Ticket\n    requires Ticket.status is \"cancel_requested\"\n    sets Ticket.approved to true\n  Cook cancels Ticket\n    requires Ticket.status is \"cancel_requested\"\n    requires Ticket.started is false or Ticket.approved is true\n    sets Ticket.status to \"cancelled\"\n";
